16:9 Manhattan skyline 1300-2025 :root {      --subject: "$entity across deep time"; /* e.g. Manhattan skyline 1600-2100, Horse evolution, The English language */     --epochs: 5; /* AI infers key representative eras */ }  # canvas {     background: linear-gradient(to right, # f4e4c1, # 2c2c2c); /* dawn to dusk of time */ }  # subject_render {     layout: "Horizontal triptych timeline with vertical depth slices";     render-left-panel: "Dawn era: heavily stylised historical art (woodcut, illuminated manuscript, fossil sketch) with contemporary descriptive labels in period script.";     render-middle-panels: "Successive eras blending into next: each era uses its dominant artistic and documentary style (daguerreotype, newsreel, CAD wireframe), AI inferring architectural or morphological details.";     render-right-panel: "Far future or present: hyper-photoreal, perhaps speculative, with weather, wear, and life — the actual light of the last era falling on it.";     transition-between-eras: "Edges between panels are ghostly palimpsests where the old form's outline still guides the new, like time-exposure of growth."; }

